-- GENERATED by `wfj generate` from data/gossip/gossip-5c.jsonl. Do not edit: `wfj validate` regenerates and diffs it.
local _, WFJ = ...
WFJ.Data.add("gossip", {
  ["5c0fca85d7acaef6"] = { "Le Segrete di ⟦Stormwind=Roccavento⟧ si trovano vicino al Quartiere dei Maghi, a ⟦Stormwind=Roccavento⟧.", "." },
  ["5c10a6490675e118"] = { "<Omarion borbotta qualcosa sottovoce.>\n\nMa certo che posso aiutarti, <caro/cara> <ragazzo/ragazza>. È il mio ultimo desiderio... la mia ultima volontà. Ti prego, prendi questo manuale. Le sue pagine raccolgono tutto ciò che so e che ho imparato negli ultimi 30 e passa anni della mia misera vita. Consegna il manuale a quel buono a nulla del mio apprendista, che probabilmente se ne sta seduto sul suo grasso deretano alla ⟦Light's Hope Chapel=Cappella della Luce⟧.", "." },
  ["5c1a55fe92220e09"] = { "Oh, è così orribile, <signore/signorina>. Casa Barov un tempo era piena di vita... piena di splendore. Il maniero era la residenza principale dei Barov, al centro del loro vasto impero.\n\nIo e Lucien notammo che, con il passare dei giorni, i Barov diventavano sempre più cupi. Abbattuti. La paranoia e la rabbia spesso sopraffacevano il padrone e la padrona. Di notte sentivamo i Barov litigare nelle loro stanze. Da quel che capimmo, la loro avidità aveva «rotto la diga», per così dire.", "." },
  ["5c2f929811c71aca"] = { "Finalmente! Naralex si risveglia dall'incubo.", "." },
  ["5c2fa921847e2f63"] = { "Il tuo corpo sembra provato e il tuo spirito stanco. Riposa sotto il nostro tetto e lascia che Elune guidi i tuoi sogni.", "." },
  ["5c303b8861bbd811"] = { "Stavolta ti sei davvero superata, signora Chambers. Neanche una macchia di muffa!", "." },
  ["5c48a7b5a89e2dc8"] = { "Mi prendi per un idiota, {race}? Tanto varrebbe che firmassi di mio pugno la sua condanna a morte! Perché dovrei fidarmi di te?", "." },
  ["5c4a81fb15e32bbf"] = { "La presenza dei draghi blu.", "." },
  ["5c4beac785fe239c"] = { "Permetto all'uomo di prendere abbastanza mais da sfamare la sua famiglia per un paio di giorni, incoraggiandolo a lasciare quelle terre.", "." },
  ["5c57e10038b6db46"] = { "Piano piano, {class}, Pele'keiki pensa che tu non sapere che tutta quella roba essere in viaggio per ⟦Silithus=Silitus⟧. A Pele'keiki hanno detto che l'ultima parte arriva là in meno di $2113w giorni, e poi qualche sciocco sconsiderato suona il gong fuori dai cancelli di ⟦Ahn'Qiraj=Ahn'qiraj⟧ per aprirli e comincia la guerra.", "." },
  ["5c617b3c8bd7df3c"] = { "%s prepara una pozione per {name}.", "." },
  ["5c61977714f290ad"] = { "A volte i nani si girano su se stessi lasciando la schiena scoperta. Approfitta di quel momento per colpire così...", "." },
  ["5c64ed8c14d25699"] = { "Eccellente, {name}! Impari davvero in fretta. Ora che conosci le basi, posso insegnarti a stringere un legame duraturo con un compagno animale.\n\nVa' con questa conoscenza e prospera. Sii <il/la> {class} di cui l'isola di Zephras ha bisogno.", "." },
  ["5c65948d4a91339e"] = { "Ora sto meglio. Torniamo a ⟦Ratchet=Porto Paranco⟧. Andiamo, {name}.", "." },
  ["5c67715b106da800"] = { "Una banda di predoni laggiù! Fuoco!", "." },
  ["5c6ad9a0bc7e8891"] = { "La macchina ne ha prese parecchie! Prepariamola per la prossima gara.", "." },
  ["5c6da2001668cbbf"] = { "Proverò un immenso piacere nel togliere la vita a questa povera disgraziata! Non è troppo tardi: non deve soffrire invano. Torna indietro e la sua morte sarà misericordiosa!", "." },
  ["5c6f688c42ade84c"] = { "Ancora? Ancora cosa??", "." },
  ["5c738ebfc71c1a28"] = { "Fa' provare me! Tu troppo stupido!", "." },
  ["5c7f28b1d408b240"] = { "E se usassimo tre focalizzatori in schema tyreano? Dovrebbe risolvere il problema.", "." },
  ["5c804a792ecdc88f"] = { "Buona Veglia delle Ombre! Ti piace la mia maschera? Fa tanta paura!", "." },
  ["5c885eed0ec0db01"] = { "La Torre di Brinarossa protegge il ⟦Iceblood Garrison=Presidio di Brinarossa⟧ da sud-est.\n\nÈ controllata dall'⟦Alliance=Alleanza⟧.", "." },
  ["5c8972ba7935274e"] = { "Non ho tempo da perdere, <straniero/straniera>. Di' cosa vuoi o vattene!", "." },
  ["5c8ab96bfbfa6b5e"] = { "Salute, <onorato/onorata>. Turak Runetotem e gli altri druidi ti aspettano nella Hall of Elders, sull'⟦Elder Rise=Altura degli Anziani⟧.", "." },
  ["5c9c51cb73f111f9"] = { "La ⟦Darkmoon Faire=Fiera di Lunacupa⟧ è l'evento più grandioso di tutta Azeroth!", "." },
  ["5ca9767a41bce8cd"] = { "Non c'è modo migliore per schiarirsi la mente che tessere.", "." },
  ["5cb0c4f5956f8223"] = { "⟦Blackfathom Deeps=Abissi di Fondocupo⟧", "." },
  ["5cb1c54793c27e49"] = { "E allora com'è morto?", "." },
  ["5cb2c03ae8d2d095"] = { "<Benvenuto/Benvenuta> al ⟦Farstrider Lodge=Padiglione Lungopasso⟧, {name}!", "." },
  ["5cb36dfc8bf96399"] = { "Buonanotte, signori. Dormite bene.", "." },
  ["5cb73eac68008573"] = { "È... È finita, lord Staghelm. Abbiamo vinto. Anche se il prezzo di questa vittoria è stato alto.", "." },
  ["5cc2d9e1bd040315"] = { "La tua commissione deve contare molto, {class}, per spingerti così a fondo nella palude...", "." },
  ["5cc4b3e5168bc593"] = { "Non amo la conversazione.", "." },
  ["5cc6dd5765352abf"] = { "Il capitano è morto.", "." },
  ["5ccbf8eb8febf8e2"] = { "È l'ultima notte della Celebrazione della Luna. Che la fortuna sia con te!", "." },
  ["5ccd4037b64f0596"] = { "Un veleno virulento colpisce %s.", "." },
  ["5ccdbd6c0b2c1ce5"] = { "%s guarda nervosamente verso Lotwil.", "." },
  ["5cd3c002cf9fd297"] = { "Bah! Qui comanda il mio potere!", "." },
  ["5ce4538819d8d86c"] = { "%s cerca di fuggire, in preda alla paura!", "." },
  ["5cf709170a13d657"] = { "So che lo farai, {name}.\n\nAnch'io sono una sacerdotessa, anche se, a differenza di te, ho lasciato questo mondo da molto tempo. Il mio spirito, però, è rimasto qui, come gli spiriti delle migliaia di persone massacrate brutalmente dal principe folle, Arthas Menethil, e dalla sua legione di non morti.", "." },
  ["5cfe76ffb1aa78ad"] = { "Alla fine ho scoperto che certe parti del cervello, se rimosse o stimolate, rendono un soggetto molto più docile.", "." },
})
